import json

# NEW theory: Keep TRAILING zeros as-is (don't fill them)
# Only fill LEADING zeros with frame color

def transform_leading_only(row, fc):
    # Fill leading zeros, preserve trailing zeros
    result = []
    for v in row:
        if v == 0 and result and result[-1] != 0:
            # After first non-zero: keep zeros until end
            result.append(v)
        elif v == 0 and not result or (result and result[-1] == 0):
            # Leading zeros: replace with frame color
            result.append(fc)
        else:
            result.append(v)
    return result

# Or simpler: find first non-zero, replace all preceding zeros with frame color
def transform_simple(row, fc):
    # Replace leading zeros with frame color, keep everything else
    first_nz = None
    for i, v in enumerate(row):
        if v != 0:
            first_nz = i
            break
    if first_nz is None:
        # All zeros - replace all with frame color?
        return [fc] * len(row)
    return [fc if i < first_nz else v for i, v in enumerate(row)]

test_bboxes = [
    [[2, 2, 2], [0, 0, 2], [0, 0, 2]],  # Shape 2
    [[4, 0, 4], [4, 0, 4], [4, 4, 4]],  # Shape 4
    [[3, 3, 3], [0, 3, 0], [3, 3, 3]],  # Shape 3
    [[0, 7, 7], [7, 7, 7], [7, 7, 0]]   # Shape 7
]

print("Transforming bboxes with simple leading-zeros rule:")
for val, bbox in zip([2, 4, 3, 7], test_bboxes):
    print(f"\nShape {val}:")
    for row in bbox:
        transformed = transform_simple(row, 8)
        print(f"  {row} -> {transformed}")

# Create full output
output = [[8] * 5 for _ in range(17)]

shapes_to_place = [
    {'val': 2, 'bbox': [[2, 2, 2], [0, 0, 2], [0, 0, 2]], 'start_row': 1},
    {'val': 4, 'bbox': [[4, 0, 4], [4, 0, 4], [4, 4, 4]], 'start_row': 5},
    {'val': 3, 'bbox': [[3, 3, 3], [0, 3, 0], [3, 3, 3]], 'start_row': 9},
    {'val': 7, 'bbox': [[0, 7, 7], [7, 7, 7], [7, 7, 0]], 'start_row': 13},
]

print("\n\nPlacing shapes:")
for s in shapes_to_place:
    for r_idx, row_vals in enumerate(s['bbox']):
        transformed = transform_simple(row_vals, 8)
        output_row = s['start_row'] + r_idx
        output[output_row][1:4] = transformed
        print(f"  Row {output_row}: {row_vals} -> {transformed}")

print("\n\nFinal output:")
for row in output:
    print(row)

submit_data = {"action": "submit", "grid": output}
print("\nSubmitting:", json.dumps(submit_data))
